import{_ as t,o as a,c as r,ag as i}from"./chunks/framework.cyF4XceO.js";const p=JSON.parse('{"title":"Serverless Container Family proposals","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/container/index.md","filePath":"proposals/container/index.md"}'),s={name:"proposals/container/index.md"};function o(n,e,d,c,l,h){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="serverless-container-family-proposals" tabindex="-1">Serverless Container Family proposals <a class="header-anchor" href="#serverless-container-family-proposals" aria-label="Permalink to &quot;Serverless Container Family proposals&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Historical / deferred candidate family</p><p><code>container.forms.takoform.com</code> is retained source from the earlier Provider projection. It is not part of the current official corpus (the single Edge family with 16 Forms), and this family is outside Current navigation. These pages are English-only historical/deferred proposals.</p></div><p>The Serverless Container Family, <code>container.forms.takoform.com</code>, was one of the families in the earlier Provider 3.0 projection (<a href="./../../spec/decisions/0043-forms-target-popular-vendor-locked-primitives.html">decision 0043</a>). Its members fix, completely, the application-visible semantics of the request-driven serverless container model — immutable revisions minted from digest-pinned OCI images, request-driven autoscaling with a concurrency target, scale-to-zero, and basis-point traffic splitting across revisions — that every major cloud offers and no de-facto standard API covers, without naming any vendor (<a href="./../../spec/decisions/0008-forms-preserve-service-shape.html">decision 0008</a>).</p><h2 id="authoring-policy-shape-preserving-contracts" tabindex="-1">Authoring policy: shape-preserving contracts <a class="header-anchor" href="#authoring-policy-shape-preserving-contracts" aria-label="Permalink to &quot;Authoring policy: shape-preserving contracts&quot;">​</a></h2><p>Every member Form preserves one service shape end to end: process contract, instance lifecycle, scaling semantics, update and delete units, error semantics, and the capabilities a revision may reach. No free semantic token is admitted; a difference in semantics is a different Form, never a selector value. Outward capability use belongs to the revision resource; inward activation is an attachment resource (<a href="./../../spec/decisions/0010-exact-interface-and-binding-contracts.html">decision 0010</a>). Desired schemas carry no <code>name</code> or envelope plumbing: the resource envelope owns identity and status (<a href="./../../spec/decisions/0011-resource-identity-generation-and-revision.html">decision 0011</a>).</p><p>The family is minted after <a href="./../../spec/decisions/0045-external-standard-services-are-sealed-slots.html">decision 0045</a>, so its revision Form carries the external standard-service declaration from birth (<a href="./../../spec/standard-services/">spec/standard-services</a>): a Container Revision reaches PostgreSQL, Redis, S3-compatible storage, or SMTP through sealed slots with opaque reverse-DNS protocol identifiers, never through endpoints or credentials in portable state — which is also how the family serves stateful applications without growing the database Forms decision 0043 swore off.</p><p>These prose documents accompany five generated Experimental <code>0.x</code> candidates under <code>forms/candidates/container.forms.takoform.com</code>. The candidate bytes are retained historical/deferred source, not the current publisher identity. Editing this directory reserves or changes no identity.</p><h2 id="the-service-aggregate" tabindex="-1">The service aggregate <a class="header-anchor" href="#the-service-aggregate" aria-label="Permalink to &quot;The service aggregate&quot;">​</a></h2><p>A Container Service has at most ONE ContainerTraffic; that traffic resource selects Container Revisions of its own identity with basis-point weights summing to exactly 10000; every attachment is admitted against it and refused when it is absent; and the identity reports itself Ready only while its traffic resource actually serves — the same aggregate statement the Edge family makes in <a href="./../../spec/decisions/0016-the-worker-aggregate-has-one-active-deployment.html">decision 0016</a>.</p><h2 id="retained-candidate-members-historical-deferred" tabindex="-1">Retained candidate members (historical/deferred) <a class="header-anchor" href="#retained-candidate-members-historical-deferred" aria-label="Permalink to &quot;Retained candidate members (historical/deferred)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Form</th><th>Role</th><th>One-line semantics</th><th>Separate-Form boundary</th></tr></thead><tbody><tr><td><a href="./container-service.html">ContainerService</a></td><td>identity</td><td>Logical identity of one request-driven container service; the runtime contract is fixed by identity.</td><td>A run-to-completion job or an event-invoked function is a different Form.</td></tr><tr><td><a href="./container-revision.html">ContainerRevision</a></td><td>revision</td><td>Immutable serving snapshot: OCI image by digest, command/args, vars, sensitive slots, external services, resources, concurrency, instance bounds.</td><td>Mutable in-place config or a host-built image is not a revision of this Form.</td></tr><tr><td><a href="./container-traffic.html">ContainerTraffic</a></td><td>deployment</td><td>Basis-point traffic split across up to eight Container Revisions of one service.</td><td>Tagged revision URLs or per-request routing are separate work.</td></tr><tr><td><a href="./container-endpoint.html">ContainerEndpoint</a></td><td>attachment</td><td>Makes the service reachable over HTTPS at an address the host assigns and publishes.</td><td>A name the author owns is <code>ContainerCustomDomain</code>.</td></tr><tr><td><a href="./container-custom-domain.html">ContainerCustomDomain</a></td><td>attachment</td><td>Serves one DNS hostname from the service&#39;s active traffic split over HTTPS.</td><td>Path-pattern routing is a separate attachment Form.</td></tr></tbody></table><p>Designs that differ in these semantics — run-to-completion jobs, addressable per-instance actors, host-built source deploys — belong to other families or later members and get their own proposals when that work starts, per <a href="./../../spec/form-families.html">spec/form-families.md</a>.</p>',12)])])}const f=t(s,[["render",o]]);export{p as __pageData,f as default};
